setup.test_slugify.py:
from slugify import slugify


def test_slugify_normalises_case_and_punctuation():
    assert slugify("Hello, World!") == "hello-world"


def test_slugify_collapses_and_trims():
    assert slugify("  Two   Spaces  ") == "two-spaces"


def test_slugify_keeps_underscores():
    assert slugify("Already-Good_1") == "already-good_1"
